const e={title:"TripReel - Kostenlose Reise-Animations-App: Verwandeln Sie Fotos in schöne Videos",description:"Erstellen Sie atemberaubende Reisevideos mit animierten Karten und Flugrouten. Kostenlose Reise-Animations-App mit 3D-Globus-Routenkartierung. Verwandeln Sie Ihre Fotos automatisch in schöne Reisevideos. Datenschutz zuerst, funktioniert offline.",keywords:"Reise-Animations-App, Reise-Karten-Animations-App, Reise-Routen-Animations-App, Flug-Animations-App, Reise-Video-Macher, automatisches Reise-Video, animierte Reise-Karte, Flugpfad-Animation, Reise-Animation, Globus-Animation, Reise-Rückblick-Video, Foto zu Video, Reise-Highlights, kostenlose Reise-App, Offline-Video-Macher, Datenschutz-Reise-App, Kamerarollen-Video"},i={logoAlt:"TripReel Logo",appName:"TripReel",howItWorks:"So funktioniert's",video:"Video",features:"Funktionen",theApp:"Die App"},n={badge:"Verwandle Fotos in Reisegeschichten",title1:"Deine Kamerarolle,",title2:"voll ausgeschöpft",description:"TripReel erstellt automatisch wunderschöne Reisevideos aus den Standorten deiner Fotos. Sieh zu, wie deine Reisen mit atemberaubenden animierten Routenkarten und Flugrouten auf einem 3D-Globus lebendig werden, während deine Daten privat und sicher bleiben.",secure:"100% sicher",worksOffline:"Funktioniert offline",globeAlt:"TripReel Globus-Animation"},t={title:"So funktioniert's",subtitle:"Drei einfache Schritte zu deinem perfekten Reisevideo",step1:{title:"Fotozugriff erlauben",description:"Gewähre TripReel Zugriff auf deine Fotobibliothek. Die App liest nur Standort-Metadaten, sonst nichts."},step2:{title:"Automatische Reiseerkennung",description:"TripReel analysiert Standort-Metadaten und findet intelligent deine Reisen anhand von Daten und Orten."},step3:{title:"Video generieren",description:"Schau zu, wie sich deine Reise auf einer wunderschönen Globus-Animation entfaltet, bereit zum Teilen in sozialen Medien."}},s={title:"Erlebe die Magie",subtitle:"Sieh, wie TripReel deine Fotobibliothek in fantastische Reisevideos verwandelt",caption:"So kann dein finales Reisevideo aussehen"},r={title:"Alles, was du brauchst",subtitle:"Leistungsstarke Funktionen für moderne Reisende",twoTap:{title:"Reisevideos mit zwei Klicks",description:"Erstelle beeindruckende Reisevideos aus deiner Fotobibliothek mit nur zwei Klicks. Keine Bearbeitung erforderlich."},smartTrip:{title:"Intelligente Reiseerkennung",description:"Findet und gruppiert automatisch deine Reisen durch Analyse von Daten und Standort-Metadaten deiner Fotos."},globe:{title:"Wunderschöne Globus-Animation",description:"Sieh zu, wie deine Reise auf einem atemberaubenden 3D-Globus lebendig wird, der deine animierten Reiserouten und Flugrouten rund um die Welt zeigt."},privacy:{title:"Datenschutz zuerst",description:"Alles wird auf deinem Gerät verarbeitet. Deine Fotos verlassen nie dein Handy. Funktioniert im Flugmodus."},customStyles:{title:"Individuelle Stile",description:"Wähle aus mehreren Globus-Stilen und Anpassungen, um deiner Ästhetik zu entsprechen und jedes Video einzigartig zu machen."},manualControl:{title:"Manuelle Steuerung",description:"Du kannst manuell komplett neue Reisen hinzufügen, falls Ortungsdienste auf deinem Gerät nicht aktiviert waren."}},a={title:"Kreative Video-Ideen",subtitle:"Lass dich inspirieren, was du mit TripReel erstellen kannst. Von schnellen Wochenendtrips bis zu jahrelangen Abenteuern, erstelle beeindruckende Reisevideos für jede Reise.",description:"Ob du eine Reisekarten-Animation erstellst, eine Flugroute dokumentierst oder eine Jahresend-Reisezusammenfassung machst, TripReel macht es mühelos, deine Erinnerungen in teilbare Videos zu verwandeln.",ideas:{yearRecap:{title:"2025 Reiserückblick",description:"Erstelle automatisch dein jährliches Reiserückblick-Video für 2025"},europeRoadTrip:{title:"Europa Roadtrip",description:"Präsentiere dein europäisches Abenteuer mit animierten Routenkarten"},southeastAsia:{title:"Südostasien-Reise",description:"Visualisiere deine Backpacking-Route durch mehrere Länder"},japanRail:{title:"Japan Zugreise",description:"Erstelle Kartenvideos deiner Zugrouten durch Japan"},crossCountry:{title:"Quer durch die USA",description:"Verwandle deinen amerikanischen Roadtrip in ein episches Routenvideo"},islandHopping:{title:"Inselhopping",description:"Zeige deine Reisen von Insel zu Insel mit atemberaubenden 3D-Animationen"},worldTour:{title:"Weltreise-Montage",description:"Mehrere Reisen in einem fantastischen globalen Reisevideo"},travelPlans:{title:"Reisepläne 2026",description:"Visualisiere und plane deine aufregenden Reiseabenteuer für 2026"},lifetimeTravel:{title:"Lebensreise-Geschichte",description:"Erstelle ein Video mit allen deinen lebenslangen Reisen"},regionalExplorer:{title:"Regional-Entdecker",description:"Kartiere deine Abenteuer durch Bundesländer, Provinzen und Regionen"},festivalCircuit:{title:"Festival-Circuit",description:"Kartiere deine Musikfestival- und Event-Reise"},bikeRoutes:{title:"Meine Städtetrips",description:"Präsentiere all deine Stadtausflüge"}}},o={title:"Die App",subtitle:"Jetzt im App Store verfügbar",alt1:"Automatische Reisevideos - Erstelle beeindruckende Videos in Sekunden",alt2:"Foto-Standorterkennung - Nutzt die Metadaten deiner Fotos",alt3:"Reiseerkennung - Gruppiert automatisch deine Reisen",alt4:"Wunderschöne Globus-Videos - Globus-Animation deiner Reise",alt5:"Individuelle Stile - Personalisiere deine Reisevideos"},d={comingSoon:"Bald verfügbar",androidTitle:"Android-App kommt bald!",androidMessage:'Die Android-Version ist noch nicht verfügbar, kommt aber bald. Schreib mir an <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> und ich informiere dich, sobald sie fertig ist!',gotIt:"Verstanden!"},l={title:"Häufig gestellte Fragen",subtitle:"Alles, was du über TripReel wissen musst",q1:{question:"Kann ich die App wirklich vollständig im Flugmodus nutzen?",answer:"Ja! Für Premium-Nutzer kann die App vollständig offline im Flugmodus ohne Einschränkungen genutzt werden. Für Nicht-Premium-Nutzer sind einige Funktionen werbefinanziert, was vorübergehendes Aktivieren des Internets erfordern könnte, aber für Premium-Nutzer gibt es keine Werbung und die App kann vollständig im Flugmodus genutzt werden."},q2:{question:"Ich habe auf Premium upgegradet, wie kann ich das Wasserzeichen entfernen?",answer:"Viele Leute fragen, welche App verwendet wurde, um diese Videos zu erstellen, daher hast du nach dem Upgrade auf Premium die Option, eine kleinere Version des Wasserzeichens hinzuzufügen (nur mit dem App-Namen) oder es komplett zu entfernen, wenn du möchtest."},q3:{question:"Sind meine Fotodaten sicher und privat?",answer:"Absolut! TripReel liest nur Standort-Metadaten deiner Fotos - wir greifen niemals auf die eigentlichen Fotoinhalte zu, speichern oder übertragen sie. Alle Verarbeitung erfolgt lokal auf deinem Gerät, und keine Daten verlassen jemals dein Handy. Du kannst dies überprüfen, indem du die App im Flugmodus verwendest - sie funktioniert perfekt offline!"},q4:{question:"Was ist, wenn meine Fotos keine Standortdaten haben?",answer:"Kein Problem! Falls Ortungsdienste nicht aktiviert waren, als du deine Fotos gemacht hast, kannst du manuell Reisen erstellen und Orte selbst hinzufügen. Die App gibt dir volle Kontrolle, um deine Reise-Timeline anzupassen."},q5:{question:"Wie erkennt die App meine Reisen automatisch?",answer:"TripReel analysiert die Standort-Metadaten und Zeitstempel deiner Fotos, um intelligent zu identifizieren, wann und wo du gereist bist. Sie gruppiert nahe Orte und Daten zusammen, um deine Reisen automatisch ohne manuelle Arbeit zu erkennen."},q6:{question:"Kann ich das Aussehen meiner Videos anpassen?",answer:"Ja! Du kannst aus mehreren Globus-Stilen wählen und verschiedene Aspekte deiner animierten Reisevideos anpassen, um deiner persönlichen Ästhetik zu entsprechen. Premium-Nutzer erhalten Zugang zu zusätzlichen Routen-Animationsstilen, Karten-Themes und Flugrouten-Optionen."},q7:{question:"Muss ich ein Konto erstellen?",answer:"Kein Konto erforderlich! TripReel funktioniert sofort nach dem Download. Keine Registrierung, kein Login und keine persönlichen Informationen nötig. Lade einfach die App herunter und beginne sofort mit der Erstellung deiner Reisevideos."},q8:{question:"Warum fehlt ein Ort in meiner Reise?",answer:"Die App kann nur mit verfügbaren Daten arbeiten, also brauchst du zunächst mindestens ein paar Fotos an diesem Ort. Zweitens musst du sicherstellen, dass Standortdaten aktiviert waren, als du dort warst. Drittens kann manchmal schlechter GPS-Empfang falsche Standortdaten verursachen. Wenn du all dies ausgeschlossen hast und dein Ort immer noch nicht angezeigt wird, kannst du diesen Ort manuell über Reiseübersicht > Bearbeiten-Button hinzufügen. Bitte nutze auch Kontakt, um das Problem zu melden."},q9:{question:"Wo kann ich mein tolles Video teilen?",answer:"Natürlich kannst du es auch auf allen Social-Media-Plattformen teilen. Um besser zur Plattform zu passen, erlaubt die App verschiedene Seitenverhältnisse für deine Videos."},q10:{question:"Wo kann ich einen Bug melden?",answer:"Kontaktiere mich einfach direkt unter marian@qod.ee und erkläre kurz, was das Problem ist."}},u={title:"E-Mail-Support",description:"Wenn du Feedback hast oder auf Probleme stößt, kontaktiere mich gerne direkt über diese E-Mail und ich werde deine Anfrage persönlich lesen und so schnell wie möglich bearbeiten. Danke, dass du die App nutzt!",close:"Schließen"},c={default:{title:"🍪 Cookies",message:"Wir verwenden Cookies auf der TripReel-Website, um dein Erlebnis zu verbessern. Es werden keine persönlichen Daten gesammelt.",accept:"Akzeptieren",decline:"Ablehnen",details:"Details"},theme:{title:"🍪 Cookies",message:"🌙 Um deine Theme-Präferenz zu speichern, musst du essenzielle Cookies auf der TripReel-Website akzeptieren. Ohne sie kann deine Theme-Wahl nicht gespeichert werden.",accept:"Akzeptieren",decline:"Ablehnen",details:"Details"}},h={privacy:"App-Datenschutzrichtlinie",cookies:"Website-Cookie-Richtlinie",contact:"Kontakt",cookiePreferences:"Cookie-Einstellungen",madeWith:"Erstellt mit",forTravelers:"für Reisende weltweit",copyright:"© {{year}} TripReel."},m={title:"Bereit, deine Reise zu teilen?",description:"Lade TripReel heute herunter und verwandle deine Kamerarolle in wunderschöne Reisevideos mit animierten Karten und Routen. Deine Abenteuer verdienen es, gefeiert zu werden.",features:"Kostenloser Download • Schnell & bequem • Datenschutz garantiert"},p={meta:e,header:i,hero:n,howItWorks:t,videoSection:s,features:r,videoIdeas:a,screenshots:o,appStore:d,faq:l,contact:u,cookieBanner:c,footer:h,cta:m};export{d as appStore,u as contact,c as cookieBanner,m as cta,p as default,l as faq,r as features,h as footer,i as header,n as hero,t as howItWorks,e as meta,o as screenshots,a as videoIdeas,s as videoSection};
